    cols=[np.ones(len(t)),x,v,x*x,x*v,v*v,x**3,x*x*v,x*v*v,v**3,v*np.abs(v),np.sign(v),np.sin(x),np.cos(x),C,S,x*C,x*S,v*C,v*S]
